(5400096, 776397, 37845, '<td valign="top">I think the colours in this shoot are good, and the texture that was created bring strength to the image.</td>', 'I think the colours in this shoot are good, and the texture that was created bring strength to the image.', '2009-03-25 11:02:27.000000', NULL, 1),
(5400098, 776212, 37845, '<td valign="top">Nice colours, and good movement in this shot. They look like the tails of goldfish.</td>', 'Nice colours, and good movement in this shot. They look like the tails of goldfish.', '2009-03-25 11:02:50.000000', NULL, 1),
(5400099, 776140, 37845, '<td valign="top">Incredible lines in this shot. The rail lines carry the viewer throughout the photo.</td>', 'Incredible lines in this shot. The rail lines carry the viewer throughout the photo.', '2009-03-25 11:03:43.000000', NULL, 1),
(5400101, 774449, 37845, '<td valign="top">Looks like a native teepee... nice verticle lines in this shot.</td>', 'Looks like a native teepee... nice verticle lines in this shot.', '2009-03-25 11:04:38.000000', NULL, 1),
(5400103, 776072, 37845, '<td valign="top">I really like the effect in this shot. The inclusion of the flag in the top, the motion in the car, the abstracted view of the stands. Outstanding shot... conveys motion really well.</td>', 'I really like the effect in this shot. The inclusion of the flag in the top, the motion in the car, the abstracted view of the stands. Outstanding shot... conveys motion really well.', '2009-03-25 11:05:32.000000', NULL, 1),
