(5401470, 776159, 105012, '<td valign="top">Stunning.</td>', 'Stunning.', '2009-03-26 00:23:38.000000', NULL, 1),
(5401473, 775899, 105012, '<td valign="top">While this obviously captures objects IN motion, it''s only because we know that birds'' wings and waves move that we know there is motion going on.  I''m not sure that''s a criticism, but I long to see in this what I would have seen if I had been there ---</td>', 'While this obviously captures objects IN motion, it''s only because we know that birds'' wings and waves move that we know there is motion going on.  I''m not sure that''s a criticism, but I long to see in this what I would have seen if I had been there ---', '2009-03-26 00:25:53.000000', NULL, 1),
