(5402873, 774467, 36141, '<td valign="top">Beautiful, you''ve ''painted'' an abstract motion. Love the composition and colors. Fits the rules perfectly.</td>', 'Beautiful, you''ve ''painted'' an abstract motion. Love the composition and colors. Fits the rules perfectly.', '2009-03-26 19:54:39.000000', NULL, 1),
