(5403345, 776257, 33068, '<td valign="top">Gorgeous texture.</td>', 'Gorgeous texture.', '2009-03-27 01:06:01.000000', NULL, 1),
(5403346, 776211, 33068, '<td valign="top">Love the colors and shapes.  NICE.</td>', 'Love the colors and shapes.  NICE.', '2009-03-27 01:06:26.000000', NULL, 1),
(5403371, 775806, 73056, '<td valign="top">Nice abstract! I like that it has a focal point and movement.</td>', 'Nice abstract! I like that it has a focal point and movement.', '2009-03-27 02:36:26.000000', NULL, 1),
(5403372, 776193, 73056, '<td valign="top">Great shot!!!! Love the abstract quality and the fact that I can identify the subject. 10!</td>', 'Great shot!!!! Love the abstract quality and the fact that I can identify the subject. 10!', '2009-03-27 02:37:24.000000', NULL, 1),
(5403374, 776156, 73056, '<td valign="top">Great shot and abstract! I like the fact that it''s abstract yet still recognizable. And the crop and title are perfect. 10!</td>', 'Great shot and abstract! I like the fact that it''s abstract yet still recognizable. And the crop and title are perfect. 10!', '2009-03-27 02:38:50.000000', NULL, 1),
(5403375, 776370, 73056, '<td valign="top">Great one! Blur, tones &amp; title. It really works. 10!</td>', 'Great one! Blur, tones & title. It really works. 10!', '2009-03-27 02:39:34.000000', NULL, 1),
(5403376, 775061, 73056, '<td valign="top">This is so great! The abstract is wonderful and the title perfect! Beautiful processing, too! 10+</td>', 'This is so great! The abstract is wonderful and the title perfect! Beautiful processing, too! 10+', '2009-03-27 02:41:58.000000', NULL, 1),
(5403377, 775701, 73056, '<td valign="top">Great abstract of this fish! Beautiful colors.</td>', 'Great abstract of this fish! Beautiful colors.', '2009-03-27 02:43:24.000000', NULL, 1),
(5403379, 776319, 73056, '<td valign="top">Great capture. Love the combination of color, blur and focus.</td>', 'Great capture. Love the combination of color, blur and focus.', '2009-03-27 02:44:09.000000', NULL, 1),
(5403380, 774710, 73056, '<td valign="top">Like it - especially since I am still able to make out the form of the car. Great abstract!</td>', 'Like it - especially since I am still able to make out the form of the car. Great abstract!', '2009-03-27 02:44:19.000000', NULL, 1),
(5403382, 775824, 73056, '<td valign="top">Great take on the challenge. Nice one.</td>', 'Great take on the challenge. Nice one.', '2009-03-27 02:53:40.000000', NULL, 1),
(5403394, 776306, 75958, '<td valign="top">not much of a abstract sadly.</td>', 'not much of a abstract sadly.', '2009-03-27 03:15:01.000000', NULL, 1),
