INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5403443, 775314, 36141, '<td valign="top">Seems there are different takes on the words ''abstract motion''. In my opinion the abstract part should cover the whole picture (Google ''abstract motion'' and look at the pictures). <br/>Abstract is: art in which the subject is represented by shapes and patterns rather than by a realistic likeness.<br/> <br/>If you had cropped out only the two spinning wheels, it would have been a perfect abstract motion.</td>', 'Seems there are different takes on the words ''abstract motion''. In my opinion the abstract part should cover the whole picture (Google ''abstract motion'' and look at the pictures). Abstract is: art in which the subject is represented by shapes and patterns rather than by a realistic likeness. If you had cropped out only the two spinning wheels, it would have been a perfect abstract motion.', '2009-03-27 06:15:50.000000', NULL, 1),
(5403445, 776294, 36141, '<td valign="top">Ah, very nice, love the motion, love the colors, love the composition.</td>', 'Ah, very nice, love the motion, love the colors, love the composition.', '2009-03-27 06:16:24.000000', NULL, 1),
(5403447, 776334, 36141, '<td valign="top">Meeting the rules, nice abstract motion.</td>', 'Meeting the rules, nice abstract motion.', '2009-03-27 06:18:04.000000', NULL, 1),
(5403449, 776381, 36141, '<td valign="top">Meeting the rules, could have been a bit more spectacular.</td>', 'Meeting the rules, could have been a bit more spectacular.', '2009-03-27 06:19:27.000000', NULL, 1),
(5403454, 775828, 36141, '<td valign="top">Yes, finally again one who understands what abstract motion means.<br/>Great shot.</td>', 'Yes, finally again one who understands what abstract motion means.Great shot.', '2009-03-27 06:20:16.000000', NULL, 1),
(5403457, 775701, 36141, '<td valign="top">Very nice abstract motion.</td>', 'Very nice abstract motion.', '2009-03-27 06:21:21.000000', NULL, 1),
(5403462, 775921, 36141, '<td valign="top">Nice take on the contest. The white isn''t too white, just right. Nice composition too.</td>', 'Nice take on the contest. The white isn''t too white, just right. Nice composition too.', '2009-03-27 06:22:36.000000', NULL, 1),
(5403464, 775018, 36141, '<td valign="top">For me it could have been a bit more abstract, but overall a very nice photo.</td>', 'For me it could have been a bit more abstract, but overall a very nice photo.', '2009-03-27 06:23:54.000000', NULL, 1),
(5403467, 775026, 36141, '<td valign="top">I would have preferred not recognizable faces, otherwise a very nice take. Love the blue.</td>', 'I would have preferred not recognizable faces, otherwise a very nice take. Love the blue.', '2009-03-27 06:25:43.000000', NULL, 1),
(5403469, 776308, 36141, '<td valign="top">Lovely abstract motion. For me it could have done without the lines in the upper right corner, they are a bit distracting.</td>', 'Lovely abstract motion. For me it could have done without the lines in the upper right corner, they are a bit distracting.', '2009-03-27 06:27:31.000000', NULL, 1),
(5403472, 776252, 36141, '<td valign="top">Meeting the rules, but I think I would have preferred a more blurry take on this one, to conceal the fact that it''s a highway.<br/> <br/>Definition of abstract: art in which the subject is represented by shapes and patterns rather than by a realistic likeness.</td>', 'Meeting the rules, but I think I would have preferred a more blurry take on this one, to conceal the fact that it''s a highway. Definition of abstract: art in which the subject is represented by shapes and patterns rather than by a realistic likeness.', '2009-03-27 06:32:32.000000', NULL, 1),
(5403474, 774734, 36141, '<td valign="top">I would have loved it more if it had been a bit more abstract. I would have cropped out the upper part.</td>', 'I would have loved it more if it had been a bit more abstract. I would have cropped out the upper part.', '2009-03-27 06:35:03.000000', NULL, 1),
(5403477, 776340, 36141, '<td valign="top">Meeting the rules perfectly. Nice abstract motion. Nice colors too.</td>', 'Meeting the rules perfectly. Nice abstract motion. Nice colors too.', '2009-03-27 06:35:47.000000', NULL, 1),
(5403483, 775427, 36141, '<td valign="top">Meeting the rules, but I would have cropped it differently. I think the lower part is the best part. Cropping just where the bright yellow vertical begins, would have made it a much stronger image.<br/>If you use your side scroll bar and move it up and down, you might see what I mean.</td>', 'Meeting the rules, but I would have cropped it differently. I think the lower part is the best part. Cropping just where the bright yellow vertical begins, would have made it a much stronger image.If you use your side scroll bar and move it up and down, you might see what I mean.', '2009-03-27 06:41:34.000000', NULL, 1),
(5403484, 775202, 36141, '<td valign="top">Ah, very nice take on the contest. Love the bright colors in this one.</td>', 'Ah, very nice take on the contest. Love the bright colors in this one.', '2009-03-27 06:42:22.000000', NULL, 1),
(5403486, 775119, 36141, '<td valign="top">Pity you didn''t crop it a bit more at the top. I would have cropped out the bended knee, it would have made it a much stronger image.</td>', 'Pity you didn''t crop it a bit more at the top. I would have cropped out the bended knee, it would have made it a much stronger image.', '2009-03-27 06:44:04.000000', NULL, 1),
(5403489, 776385, 36141, '<td valign="top">It''s meeting the rules. I would have cropped out the lower part, those little lines are a bit distracting.</td>', 'It''s meeting the rules. I would have cropped out the lower part, those little lines are a bit distracting.', '2009-03-27 06:46:51.000000', NULL, 1),
(5403492, 775243, 36141, '<td valign="top">The motion is ok, but I would have preferred a bit more abstract.</td>', 'The motion is ok, but I would have preferred a bit more abstract.', '2009-03-27 06:48:36.000000', NULL, 1),
(5403494, 776306, 36141, '<td valign="top">Abstract is: art in which the subject is represented by shapes and patterns rather than by a realistic likeness.<br/> <br/>In my opinion abstract motion should be on the whole image.</td>', 'Abstract is: art in which the subject is represented by shapes and patterns rather than by a realistic likeness. In my opinion abstract motion should be on the whole image.', '2009-03-27 06:52:42.000000', NULL, 1),
(5403498, 776007, 36141, '<td valign="top">It''s meeting the rules, but I would have cropped it differently, for instance just around the actual catch. It would have filled the whole image and would have made a much more interesting photo.</td>', 'It''s meeting the rules, but I would have cropped it differently, for instance just around the actual catch. It would have filled the whole image and would have made a much more interesting photo.', '2009-03-27 06:57:33.000000', NULL, 1),
(5403500, 776070, 36141, '<td valign="top">Definition of abstract is: art in which the subject is represented by shapes and patterns rather than by a realistic likeness.<br/> <br/>The abstract motion here is only found in a small part of the background.</td>', 'Definition of abstract is: art in which the subject is represented by shapes and patterns rather than by a realistic likeness. The abstract motion here is only found in a small part of the background.', '2009-03-27 07:00:24.000000', NULL, 1),
(5403502, 775402, 36141, '<td valign="top">Definition of abstract is: art in which the subject is represented by shapes and patterns rather than by a realistic likeness.<br/> <br/>Yours is rather a stopped motion in stead of an abstract motion.</td>', 'Definition of abstract is: art in which the subject is represented by shapes and patterns rather than by a realistic likeness. Yours is rather a stopped motion in stead of an abstract motion.', '2009-03-27 07:01:41.000000', NULL, 1),
