(5404337, 776319, 103142, '<td valign="top">Interesting shot... I wish the background could have been completely dark, the lower right seems distracting. Fun colors, though!</td>', 'Interesting shot... I wish the background could have been completely dark, the lower right seems distracting. Fun colors, though!', '2009-03-27 19:45:03.000000', NULL, 1),
(5404338, 774737, 103142, '<td valign="top">Very, very cool shot! I hope you tell us how you did it.</td>', 'Very, very cool shot! I hope you tell us how you did it.', '2009-03-27 19:45:20.000000', NULL, 1),
(5404339, 776294, 96823, '<td valign="top">Nicely done! Nice colors, lighting is good.</td>', 'Nicely done! Nice colors, lighting is good.', '2009-03-27 19:45:25.000000', NULL, 1),
(5404341, 775043, 53316, '<td valign="top">This is my very favorite in this challenge. Light streaks without having the light dominating the whole photo - instead, there''s a lovely background. The light streaks also look natural and flow together nicely. Colors and contrast is great as well. Looking at the image, I aspire to have my motion-type shots display this level of technical ability, and I also see that it has a lot of emotion, which I personally find important in abstract images. Great job.</td>', 'This is my very favorite in this challenge. Light streaks without having the light dominating the whole photo - instead, there''s a lovely background. The light streaks also look natural and flow together nicely. Colors and contrast is great as well. Looking at the image, I aspire to have my motion-type shots display this level of technical ability, and I also see that it has a lot of emotion, which I personally find important in abstract images. Great job.', '2009-03-27 19:45:36.000000', NULL, 1),
(5404342, 776342, 96823, '<td valign="top">Nice shot&gt;</td>', 'Nice shot>', '2009-03-27 19:45:45.000000', NULL, 1),
