(5404439, 776166, 103142, '<td valign="top">I''ve been using the definition: "Of, relating to, or being a style of art in which natural objects are not represented realistically." While the background is very abstract, having the main subject be so realistic doesn''t make the overall picture very abstract, IMO. Sorry!</td>', 'I''ve been using the definition: "Of, relating to, or being a style of art in which natural objects are not represented realistically." While the background is very abstract, having the main subject be so realistic doesn''t make the overall picture very abstract, IMO. Sorry!', '2009-03-27 20:51:05.000000', NULL, 1),
(5404440, 776347, 103142, '<td valign="top">I like it--especially the splash of blue. Abstract enough for me!</td>', 'I like it--especially the splash of blue. Abstract enough for me!', '2009-03-27 20:51:37.000000', NULL, 1),
(5404441, 776377, 103142, '<td valign="top">Very interesting shot! Nicely done.</td>', 'Very interesting shot! Nicely done.', '2009-03-27 20:51:50.000000', NULL, 1),
(5404442, 776227, 103142, '<td valign="top">That actually turned out quite cool. Interesting choice, nicely done.</td>', 'That actually turned out quite cool. Interesting choice, nicely done.', '2009-03-27 20:52:14.000000', NULL, 1),
(5404443, 776007, 103142, '<td valign="top">The title actually helps it a lot, but, I''m sorry, the image wasn''t very compelling without it.</td>', 'The title actually helps it a lot, but, I''m sorry, the image wasn''t very compelling without it.', '2009-03-27 20:53:49.000000', NULL, 1),
(5404445, 776244, 103142, '<td valign="top">Interesting idea. I love the bottom half of the picture, but I think the top distracts from it. Maybe cropping it down a bit to place less emphasis on the top?</td>', 'Interesting idea. I love the bottom half of the picture, but I think the top distracts from it. Maybe cropping it down a bit to place less emphasis on the top?', '2009-03-27 20:54:57.000000', NULL, 1),
