(5405117, 776367, 96823, '<td valign="top">Nice shot but there sould have been more motion with the kids IMO.</td>', 'Nice shot but there sould have been more motion with the kids IMO.', '2009-03-28 11:29:10.000000', NULL, 1),
(5405134, 776327, 97166, '<td valign="top">Some crazy chaos going on here, and it almost reminds me of a Jackson Pollock work.  I''m left only wishing that the color play was a little more cohesive, but I guess ye takes what ye gets in situations like this.</td>', 'Some crazy chaos going on here, and it almost reminds me of a Jackson Pollock work.  I''m left only wishing that the color play was a little more cohesive, but I guess ye takes what ye gets in situations like this.', '2009-03-28 11:51:40.000000', NULL, 1),
(5405136, 775236, 97166, '<td valign="top">Abstract concept, but a little too subtle for me.  The photo as a whole loses the abstract notion more, and while we see that there was a progression of your model, the ''movement'' isn''t noticeable so much, and therefore the motion aspect is also slim.</td>', 'Abstract concept, but a little too subtle for me.  The photo as a whole loses the abstract notion more, and while we see that there was a progression of your model, the ''movement'' isn''t noticeable so much, and therefore the motion aspect is also slim.', '2009-03-28 11:53:11.000000', NULL, 1),
(5405139, 776370, 97166, '<td valign="top">I like the toning that you''ve chosen here, and the motion does strengthen the shot.  The abstract feel is certainly there, but loses a little bit both because of the redundancy of your title, and the recognition factor of your model.</td>', 'I like the toning that you''ve chosen here, and the motion does strengthen the shot.  The abstract feel is certainly there, but loses a little bit both because of the redundancy of your title, and the recognition factor of your model.', '2009-03-28 11:54:29.000000', NULL, 1),
(5405140, 775828, 97166, '<td valign="top">Some brilliant light play, reminding me of a few coronas of the sun blending together.  Could have done without your redundant (and identifying) title.</td>', 'Some brilliant light play, reminding me of a few coronas of the sun blending together.  Could have done without your redundant (and identifying) title.', '2009-03-28 11:55:21.000000', NULL, 1),
(5405142, 776237, 97166, '<td valign="top">Certainly a motion shot, but the abstract is tenuous at best, and combined with the redundancy of the title, leaves me wishing for more.</td>', 'Certainly a motion shot, but the abstract is tenuous at best, and combined with the redundancy of the title, leaves me wishing for more.', '2009-03-28 11:56:01.000000', NULL, 1),
(5405144, 775026, 97166, '<td valign="top">The motion evident in this shot is far too subtle for such a challenge topic.  The abstract is stronger, but mainly falls within conceptual lines, rather than visual, which is probably a damper on DPC for a challenge of this type.</td>', 'The motion evident in this shot is far too subtle for such a challenge topic.  The abstract is stronger, but mainly falls within conceptual lines, rather than visual, which is probably a damper on DPC for a challenge of this type.', '2009-03-28 11:57:18.000000', NULL, 1),
(5405145, 775584, 97166, '<td valign="top">A very nice exhibition of line and color, but the motion aspect is a little too subtle for me.</td>', 'A very nice exhibition of line and color, but the motion aspect is a little too subtle for me.', '2009-03-28 11:58:09.000000', NULL, 1),
(5405147, 774821, 97166, '<td valign="top">I''m not really getting much of a sense of ''motion'' from this.  I can see the zoom, but the overall piece remains rather static.</td>', 'I''m not really getting much of a sense of ''motion'' from this.  I can see the zoom, but the overall piece remains rather static.', '2009-03-28 11:58:50.000000', NULL, 1),
(5405148, 776146, 97166, '<td valign="top">A nice sense of motion, but the abstract isn''t quite strong enough for me.  I know what this is, and what it is doing, and your title identifies it even further.  For me, this does not exemplify what an abstract piece should.</td>', 'A nice sense of motion, but the abstract isn''t quite strong enough for me.  I know what this is, and what it is doing, and your title identifies it even further.  For me, this does not exemplify what an abstract piece should.', '2009-03-28 11:59:54.000000', NULL, 1),
(5405149, 776293, 97166, '<td valign="top">No sense of abstract for me in this shot whatsoever, and the motion is a little too subtle.</td>', 'No sense of abstract for me in this shot whatsoever, and the motion is a little too subtle.', '2009-03-28 12:00:35.000000', NULL, 1),
(5405150, 775254, 97166, '<td valign="top">Some nice color play, but compositionally I''m not overly interested.  The frame is filled a little too much, and thus the sense of motion is lessened.</td>', 'Some nice color play, but compositionally I''m not overly interested.  The frame is filled a little too much, and thus the sense of motion is lessened.', '2009-03-28 12:01:35.000000', NULL, 1),
(5405151, 776377, 97166, '<td valign="top">A nice use of zoom for motion blur here, but I''m left underwhelmed overall. The piece is a little dark and flat and the abstract element isn''t very strong in my eyes.</td>', 'A nice use of zoom for motion blur here, but I''m left underwhelmed overall. The piece is a little dark and flat and the abstract element isn''t very strong in my eyes.', '2009-03-28 12:02:28.000000', NULL, 1),
(5405157, 776153, 97166, '<td valign="top">For me, lines across a screen don''t really convey motion in and of themselves.  There needs to be some kind of anchor. Some kind of element that grounds us and reminds us that yes, there IS something moving in this shot.  This does not convey that to me.</td>', 'For me, lines across a screen don''t really convey motion in and of themselves.  There needs to be some kind of anchor. Some kind of element that grounds us and reminds us that yes, there IS something moving in this shot.  This does not convey that to me.', '2009-03-28 12:05:40.000000', NULL, 1),
(5405158, 776316, 97166, '<td valign="top">I''m really enjoying the color play here, but the sense o movement/motion isn''t extremely evident.</td>', 'I''m really enjoying the color play here, but the sense o movement/motion isn''t extremely evident.', '2009-03-28 12:06:06.000000', NULL, 1),
(5405163, 776344, 97166, '<td valign="top">A wonderful piece that reminds me very much of a pastel or colored chalk drawing.  While the title is slightly redundant, it doesn''t hurt this one as much as some others have.  The thick lines at the top right moving into the more subtle and smooth gradation at the bottom right are what really give this one the sense of motion that might otherwise have looked more static in another piece showing simple line work.</td>', 'A wonderful piece that reminds me very much of a pastel or colored chalk drawing.  While the title is slightly redundant, it doesn''t hurt this one as much as some others have.  The thick lines at the top right moving into the more subtle and smooth gradation at the bottom right are what really give this one the sense of motion that might otherwise have looked more static in another piece showing simple line work.', '2009-03-28 12:08:24.000000', NULL, 1),
(5405164, 776359, 97166, '<td valign="top">A nice use of zoom blur here, and I like the dark aspect to it with the gorgeous blue tones.</td>', 'A nice use of zoom blur here, and I like the dark aspect to it with the gorgeous blue tones.', '2009-03-28 12:08:56.000000', NULL, 1),
(5405165, 776193, 97166, '<td valign="top">A little soft on the Abstract aspect, although you''ve nailed the motion part.</td>', 'A little soft on the Abstract aspect, although you''ve nailed the motion part.', '2009-03-28 12:09:15.000000', NULL, 1),
(5405169, 776397, 97166, '<td valign="top">What a wonderful feel to this more simple offering.  It''s almost as if you took pastels and did a rubbing on a sandstone (or similar type) surface.  Wonderful texture to it.  I would have preferred a title that didn''t identify the subject matter.</td>', 'What a wonderful feel to this more simple offering.  It''s almost as if you took pastels and did a rubbing on a sandstone (or similar type) surface.  Wonderful texture to it.  I would have preferred a title that didn''t identify the subject matter.', '2009-03-28 12:10:20.000000', NULL, 1),
(5405176, 775514, 97166, '<td valign="top">A nice attempt, but the overall feel is flat and dark.  There also seems to be no real compositional value to this.  Getting the light play to be brighter and the colors to stand out more would be a benefit, and try to remember composition as well. Give the viewer something more to think about than just a seemingly random swath through your frame.  <br/> <br/>The title, as well, is redundant and unnecessary as identifying what your abstract is is kind of defeating your purpose.</td>', 'A nice attempt, but the overall feel is flat and dark.  There also seems to be no real compositional value to this.  Getting the light play to be brighter and the colors to stand out more would be a benefit, and try to remember composition as well. Give the viewer something more to think about than just a seemingly random swath through your frame.   The title, as well, is redundant and unnecessary as identifying what your abstract is is kind of defeating your purpose.', '2009-03-28 12:13:18.000000', NULL, 1),
(5405178, 775910, 97166, '<td valign="top">Now this is quite brilliant in tone and lighting.  I feel as if I''m swimming in the darker depths of the sea, and coming across a creature seldom seen by humanity''s eyes.  Gorgeous and iridescent.</td>', 'Now this is quite brilliant in tone and lighting.  I feel as if I''m swimming in the darker depths of the sea, and coming across a creature seldom seen by humanity''s eyes.  Gorgeous and iridescent.', '2009-03-28 12:14:21.000000', NULL, 1),
(5405179, 776050, 97166, '<td valign="top">Not very strong on the abstract aspect at all, but the motion is quite evident.  Even trying to consider this on a more conceptual abstract level, I can''t really attach any significance to it.</td>', 'Not very strong on the abstract aspect at all, but the motion is quite evident.  Even trying to consider this on a more conceptual abstract level, I can''t really attach any significance to it.', '2009-03-28 12:15:10.000000', NULL, 1),
(5405185, 775555, 97166, '<td valign="top">Some nice soft toning here, and reminds me greatly of paintings on black velvet that you would display under a lamp. (One of the great kitsch art movements of the 60s and 70s I''d love to see make a comeback).</td>', 'Some nice soft toning here, and reminds me greatly of paintings on black velvet that you would display under a lamp. (One of the great kitsch art movements of the 60s and 70s I''d love to see make a comeback).', '2009-03-28 12:18:33.000000', NULL, 1),
(5405187, 776357, 97166, '<td valign="top">I''m not really sure what to think about this one actually.  It''s a little haunting, and the toning helps give it that feel, but there''s also something a little off-putting about it.   Perhaps that''s a strength.</td>', 'I''m not really sure what to think about this one actually.  It''s a little haunting, and the toning helps give it that feel, but there''s also something a little off-putting about it.   Perhaps that''s a strength.', '2009-03-28 12:19:37.000000', NULL, 1),
(5405188, 776023, 97166, '<td valign="top">I like the colors, although the sense of motion, while evident in the individual lines, isn''t really evident in the piece as a whole.</td>', 'I like the colors, although the sense of motion, while evident in the individual lines, isn''t really evident in the piece as a whole.', '2009-03-28 12:20:41.000000', NULL, 1),
(5405191, 775917, 97166, '<td valign="top">Some nice motion blur, but for my eyes, the photo just seems to fragment and doesn''t really come together as a cohesive piece for me.</td>', 'Some nice motion blur, but for my eyes, the photo just seems to fragment and doesn''t really come together as a cohesive piece for me.', '2009-03-28 12:21:23.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5405192, 775442, 97166, '<td valign="top">A little too subtle on the abstract aspect, but outside of that I like this. It stands on its own very well as a photograph, but in this challenge, just doesn''t have the strength to stand out.</td>', 'A little too subtle on the abstract aspect, but outside of that I like this. It stands on its own very well as a photograph, but in this challenge, just doesn''t have the strength to stand out.', '2009-03-28 12:22:15.000000', NULL, 1),
