(5405587, 775202, 101256, '<td valign="top">A total riot of color, effective use of grain and the non-conformity of the shapes are efficient and evocative.</td>', 'A total riot of color, effective use of grain and the non-conformity of the shapes are efficient and evocative.', '2009-03-28 18:40:49.000000', NULL, 1),
(5405588, 776074, 101256, '<td valign="top">Over all a 10, but the white blooms detract from the over all impact. The red shifts are nicely done.</td>', 'Over all a 10, but the white blooms detract from the over all impact. The red shifts are nicely done.', '2009-03-28 18:41:38.000000', NULL, 1),
(5405589, 776124, 86895, '<td valign="top">Perhaps if you focused more on one lamp it would give more emphasis on the abstract part of the challenge.</td>', 'Perhaps if you focused more on one lamp it would give more emphasis on the abstract part of the challenge.', '2009-03-28 18:41:49.000000', NULL, 1),
(5405590, 774737, 101256, '<td valign="top">Time lapsing can be dreadful sometimes, but in several senses, this is a compelling image - one can interpret it as snow, birds, dandelion seeds - very clever.  Nice capture.</td>', 'Time lapsing can be dreadful sometimes, but in several senses, this is a compelling image - one can interpret it as snow, birds, dandelion seeds - very clever.  Nice capture.', '2009-03-28 18:43:40.000000', NULL, 1),
(5405591, 776367, 86895, '<td valign="top">This is a nice shot, just not sure it''s abstract.</td>', 'This is a nice shot, just not sure it''s abstract.', '2009-03-28 18:44:47.000000', NULL, 1),
(5405593, 774647, 86895, '<td valign="top">Nice job capturing movement, maybe a tighter crop on the pendulum would make it look more abstract.</td>', 'Nice job capturing movement, maybe a tighter crop on the pendulum would make it look more abstract.', '2009-03-28 18:45:46.000000', NULL, 1),
(5405594, 775043, 101256, '<td valign="top">A nine for use of color, but the image doesn''t quite build up the tension one would expect for objects in motion - it''s meaningless in that sense - you can tell it motion, but what motion?</td>', 'A nine for use of color, but the image doesn''t quite build up the tension one would expect for objects in motion - it''s meaningless in that sense - you can tell it motion, but what motion?', '2009-03-28 18:46:41.000000', NULL, 1),
(5405596, 776317, 86895, '<td valign="top">The colours are really nice and I get the feeling of things softly floating.</td>', 'The colours are really nice and I get the feeling of things softly floating.', '2009-03-28 18:47:42.000000', NULL, 1),
(5405597, 775784, 101256, '<td valign="top">The first minimalist motion abstract I''ve seen that is almost perfect. Unfortunately, the streaking of the of the white background face is distracting and detract from the image overall.</td>', 'The first minimalist motion abstract I''ve seen that is almost perfect. Unfortunately, the streaking of the of the white background face is distracting and detract from the image overall.', '2009-03-28 18:48:26.000000', NULL, 1),
(5405598, 776206, 86895, '<td valign="top">Nice job with the feeling of motion and the border is nice too.</td>', 'Nice job with the feeling of motion and the border is nice too.', '2009-03-28 18:49:07.000000', NULL, 1),
(5405599, 775706, 101256, '<td valign="top">This would have rated a ten if there was less of a jumble of color and movement.  This is one image that would benefit from less color and motion than more.</td>', 'This would have rated a ten if there was less of a jumble of color and movement.  This is one image that would benefit from less color and motion than more.', '2009-03-28 18:49:15.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5405600, 775832, 86895, '<td valign="top">Nice job capturing motion, not sure it''s abstract.</td>', 'Nice job capturing motion, not sure it''s abstract.', '2009-03-28 18:49:37.000000', NULL, 1),
(5405601, 774501, 101256, '<td valign="top">The perfect abstract - purposeful, clever conversion and the post-modernist feel of this is wonderful.  It deserves to win.</td>', 'The perfect abstract - purposeful, clever conversion and the post-modernist feel of this is wonderful.  It deserves to win.', '2009-03-28 18:50:22.000000', NULL, 1),
(5405603, 775314, 86895, '<td valign="top">Nice job capturing motion.  Maybe if you focused on one of the rides and cropped everything else out it may look a little more abstract.</td>', 'Nice job capturing motion.  Maybe if you focused on one of the rides and cropped everything else out it may look a little more abstract.', '2009-03-28 18:50:37.000000', NULL, 1),
(5405605, 776402, 86895, '<td valign="top">Are these those Star Trek elevators? ;)  Nice colours!</td>', 'Are these those Star Trek elevators? ;)  Nice colours!', '2009-03-28 18:52:54.000000', NULL, 1),
(5405607, 775260, 86895, '<td valign="top">This is fantastic!!  Great representation of the challenge!!</td>', 'This is fantastic!!  Great representation of the challenge!!', '2009-03-28 18:53:52.000000', NULL, 1),
(5405609, 776139, 86895, '<td valign="top">Great job showing motion.</td>', 'Great job showing motion.', '2009-03-28 18:54:13.000000', NULL, 1),
(5405610, 776239, 86895, '<td valign="top">GREAT job showing motion! Maybe a tighter crop on the squirrels would give it more of an abstract look.</td>', 'GREAT job showing motion! Maybe a tighter crop on the squirrels would give it more of an abstract look.', '2009-03-28 18:55:09.000000', NULL, 1),
(5405612, 775580, 86895, '<td valign="top">Nice job capturing motion!  The colours are so soft and subtle, very nice!</td>', 'Nice job capturing motion!  The colours are so soft and subtle, very nice!', '2009-03-28 18:56:20.000000', NULL, 1),
(5405613, 775785, 86895, '<td valign="top">Nice job capturing motion!</td>', 'Nice job capturing motion!', '2009-03-28 18:56:38.000000', NULL, 1),
(5405615, 775823, 86895, '<td valign="top">Definitely has that feeling of motion! :)</td>', 'Definitely has that feeling of motion! :)', '2009-03-28 18:57:55.000000', NULL, 1),
(5405617, 774994, 86895, '<td valign="top">Fantastic job on the motion, it really looks like it''s moving! The colours work well too.</td>', 'Fantastic job on the motion, it really looks like it''s moving! The colours work well too.', '2009-03-28 18:59:11.000000', NULL, 1),
(5405620, 776231, 86895, '<td valign="top">Definitely has the feeling of motion.  The border is nice too.</td>', 'Definitely has the feeling of motion.  The border is nice too.', '2009-03-28 19:00:08.000000', NULL, 1),
(5405622, 776390, 86895, '<td valign="top">First thing that popped into my head was, this would''ve been an awesome sculpture in an 80''s night club!  The colours are really great!</td>', 'First thing that popped into my head was, this would''ve been an awesome sculpture in an 80''s night club!  The colours are really great!', '2009-03-28 19:01:17.000000', NULL, 1),
(5405624, 775061, 86895, '<td valign="top">This is a great representation of the challenge.  It reminds me of Renoir''s dancers.</td>', 'This is a great representation of the challenge.  It reminds me of Renoir''s dancers.', '2009-03-28 19:02:33.000000', NULL, 1),
(5405625, 775909, 86895, '<td valign="top">It''s a really nice picture, but I''m not sure it''s abstract.</td>', 'It''s a really nice picture, but I''m not sure it''s abstract.', '2009-03-28 19:03:03.000000', NULL, 1),
(5405626, 776363, 86895, '<td valign="top">Great job capturing movement.  You could have "cut" this in half and had two nice photos.</td>', 'Great job capturing movement.  You could have "cut" this in half and had two nice photos.', '2009-03-28 19:04:45.000000', NULL, 1),
(5405628, 776242, 86895, '<td valign="top">Nice job on the motion!  Maybe a tighter crop on the subject would make it look more abstract.</td>', 'Nice job on the motion!  Maybe a tighter crop on the subject would make it look more abstract.', '2009-03-28 19:05:23.000000', NULL, 1),
(5405632, 776089, 86895, '<td valign="top">Definitely has an abstract look to it.</td>', 'Definitely has an abstract look to it.', '2009-03-28 19:06:22.000000', NULL, 1),
(5405634, 774700, 86895, '<td valign="top">This is fun, it looks like a kid came along and knocked down the building blocks! :)</td>', 'This is fun, it looks like a kid came along and knocked down the building blocks! :)', '2009-03-28 19:07:09.000000', NULL, 1),
(5405635, 776237, 86895, '<td valign="top">Excellent job on the motion!  It really does look like it''s moving!</td>', 'Excellent job on the motion!  It really does look like it''s moving!', '2009-03-28 19:07:37.000000', NULL, 1),
(5405636, 776003, 86895, '<td valign="top">Good job showing the motion!</td>', 'Good job showing the motion!', '2009-03-28 19:08:26.000000', NULL, 1),
(5405638, 775255, 101256, '<td valign="top">This is great and it tracks very well, but it''s not abstract.  Great action shot of a Herring Gull though - nicely done.</td>', 'This is great and it tracks very well, but it''s not abstract.  Great action shot of a Herring Gull though - nicely done.', '2009-03-28 19:09:04.000000', NULL, 1),
(5405639, 774592, 86895, '<td valign="top">The colours are really pretty! Nice job on the motion, this looks like an abstract watercolour painting.</td>', 'The colours are really pretty! Nice job on the motion, this looks like an abstract watercolour painting.', '2009-03-28 19:09:24.000000', NULL, 1),
(5405640, 776212, 101256, '<td valign="top">Again, nearly perfect, but the motion is a little too long - not short enough to provide some detail that will allow for the author''s intent.</td>', 'Again, nearly perfect, but the motion is a little too long - not short enough to provide some detail that will allow for the author''s intent.', '2009-03-28 19:09:42.000000', NULL, 1),
(5405642, 776196, 101256, '<td valign="top">Another wonderful composition of light, motion and color, but it''s much too busy to be compelling enough for a 10.</td>', 'Another wonderful composition of light, motion and color, but it''s much too busy to be compelling enough for a 10.', '2009-03-28 19:10:30.000000', NULL, 1),
(5405643, 776089, 101256, '<td valign="top">Another attempt at color which is very clever and a lot of dimension, but the effect is overdone leading to some discomfort in terms of acceptable as perfectly abstract.</td>', 'Another attempt at color which is very clever and a lot of dimension, but the effect is overdone leading to some discomfort in terms of acceptable as perfectly abstract.', '2009-03-28 19:11:31.000000', NULL, 1),
(5405648, 775701, 101256, '<td valign="top">The color is washed out, but servicable in this context.  Another image that could have used a slower shutter speed to keep the total motion effect, but resulting in more saturation which would have made it a ten.</td>', 'The color is washed out, but servicable in this context.  Another image that could have used a slower shutter speed to keep the total motion effect, but resulting in more saturation which would have made it a ten.', '2009-03-28 19:12:52.000000', NULL, 1),
(5405650, 776255, 86895, '<td valign="top">Great job capturing motion! I would like to see a tighter crop, the two vertical lines on the right are kind of distracting to me.</td>', 'Great job capturing motion! I would like to see a tighter crop, the two vertical lines on the right are kind of distracting to me.', '2009-03-28 19:13:53.000000', NULL, 1),
(5405651, 775436, 86895, '<td valign="top">Nice job showing motion!</td>', 'Nice job showing motion!', '2009-03-28 19:14:12.000000', NULL, 1),
(5405652, 775968, 101256, '<td valign="top">Simple and effective - minimalist without being overly so - not perfect because of the Coriolis from black to grey.  Could have used more saturation.</td>', 'Simple and effective - minimalist without being overly so - not perfect because of the Coriolis from black to grey.  Could have used more saturation.', '2009-03-28 19:14:42.000000', NULL, 1),
(5405654, 776319, 101256, '<td valign="top">Effective, but the image is flawed by artifacts which are extremely distracting to the eye.</td>', 'Effective, but the image is flawed by artifacts which are extremely distracting to the eye.', '2009-03-28 19:15:18.000000', NULL, 1),
(5405655, 775119, 86895, '<td valign="top">Too bad this basic editing, you could have put smoke and flames under those fast feet! :)</td>', 'Too bad this basic editing, you could have put smoke and flames under those fast feet! :)', '2009-03-28 19:15:37.000000', NULL, 1),
(5405656, 776353, 86895, '<td valign="top">Great job showing motion!</td>', 'Great job showing motion!', '2009-03-28 19:16:02.000000', NULL, 1),
(5405657, 775314, 101256, '<td valign="top">Not an abstract. Which is not to say it''s a defective image - it''s not at all - it''s very good and could well be some type of commercial stock shot - it''s just not an abstract.</td>', 'Not an abstract. Which is not to say it''s a defective image - it''s not at all - it''s very good and could well be some type of commercial stock shot - it''s just not an abstract.', '2009-03-28 19:16:18.000000', NULL, 1),
(5405658, 776397, 101256, '<td valign="top">An abstract has to convey something beyond just color and light. While a good capture, this is abstract only in the sense of being blurred = in short, meaningless.</td>', 'An abstract has to convey something beyond just color and light. While a good capture, this is abstract only in the sense of being blurred = in short, meaningless.', '2009-03-28 19:17:25.000000', NULL, 1),
(5405660, 775330, 97166, '<td valign="top">Not the strongest connection to an abstract challenge in my view. The title is perhaps the most abstract aspect to it, and that''s unfortunate.   Some nice energy on the motion side, however.</td>', 'Not the strongest connection to an abstract challenge in my view. The title is perhaps the most abstract aspect to it, and that''s unfortunate.   Some nice energy on the motion side, however.', '2009-03-28 19:18:10.000000', NULL, 1),
(5405661, 775913, 101256, '<td valign="top">This is a good image, but needs some more processing treatment - as a pure photographic abstract, it fails to be interesting, but it is an effective blending of color.</td>', 'This is a good image, but needs some more processing treatment - as a pure photographic abstract, it fails to be interesting, but it is an effective blending of color.', '2009-03-28 19:18:26.000000', NULL, 1),
(5405662, 775909, 101256, '<td valign="top">Great action photo - it''s not an abstract.</td>', 'Great action photo - it''s not an abstract.', '2009-03-28 19:18:45.000000', NULL, 1),
(5405663, 776367, 97166, '<td valign="top">I''m not really getting an abstract feel out of this myself, and the motion is only really evident in the lights above the main subject.  The harsh flash lighting is also not my favorite.</td>', 'I''m not really getting an abstract feel out of this myself, and the motion is only really evident in the lights above the main subject.  The harsh flash lighting is also not my favorite.', '2009-03-28 19:18:54.000000', NULL, 1),
(5405665, 775969, 97166, '<td valign="top">Interesting, but not really a strong abstract in my view.  It''s surrealistic, but that''s not always the same thing.</td>', 'Interesting, but not really a strong abstract in my view.  It''s surrealistic, but that''s not always the same thing.', '2009-03-28 19:19:45.000000', NULL, 1),
(5405666, 776348, 101256, '<td valign="top">Very good in concept, not so much in execution.  The white bloom is distracting and does nothing for the overall contruction.  Might have been better to post process the white bloom to something different.</td>', 'Very good in concept, not so much in execution.  The white bloom is distracting and does nothing for the overall contruction.  Might have been better to post process the white bloom to something different.', '2009-03-28 19:20:02.000000', NULL, 1),
(5405670, 776360, 101256, '<td valign="top">This is one of the images I was torn over - it''s extremely clever, an excellant use of color, shutter speeds and the use of the window for different effects.  On the other hand, I just don''t like it for reasons I can''t effectively articulate.  So I rated it an 8 - I suspect others would probably rate it a 10 and it is certainly worthy of that - just not to me.</td>', 'This is one of the images I was torn over - it''s extremely clever, an excellant use of color, shutter speeds and the use of the window for different effects.  On the other hand, I just don''t like it for reasons I can''t effectively articulate.  So I rated it an 8 - I suspect others would probably rate it a 10 and it is certainly worthy of that - just not to me.', '2009-03-28 19:22:19.000000', NULL, 1),
(5405671, 774969, 101256, '<td valign="top">Again, not an abstract - great time lapse - not abstract in any sense.</td>', 'Again, not an abstract - great time lapse - not abstract in any sense.', '2009-03-28 19:22:50.000000', NULL, 1),
(5405674, 775966, 101256, '<td valign="top">I believe I know what the author was aiming at - I just feel it lacks proper execution. The Matrix style attempt is good though.</td>', 'I believe I know what the author was aiming at - I just feel it lacks proper execution. The Matrix style attempt is good though.', '2009-03-28 19:23:59.000000', NULL, 1),
(5405675, 774700, 101256, '<td valign="top">The use of color is very good and the dimensional components are very interesting, but it lacks impact.</td>', 'The use of color is very good and the dimensional components are very interesting, but it lacks impact.', '2009-03-28 19:25:15.000000', NULL, 1),
(5405676, 775899, 101256, '<td valign="top">Not an abstract - action shot of decent quality.</td>', 'Not an abstract - action shot of decent quality.', '2009-03-28 19:25:43.000000', NULL, 1),
(5405677, 776255, 101256, '<td valign="top">I don''t mean to be mean, but why bother submitting this? Ill concieved, grainy and totally devoid of any interest.</td>', 'I don''t mean to be mean, but why bother submitting this? Ill concieved, grainy and totally devoid of any interest.', '2009-03-28 19:26:43.000000', NULL, 1),
(5405681, 775910, 86895, '<td valign="top">The colours are really nice!</td>', 'The colours are really nice!', '2009-03-28 19:28:17.000000', NULL, 1),
(5405683, 776385, 86895, '<td valign="top">Nice representation of the challenge! Great sense of motion here!</td>', 'Nice representation of the challenge! Great sense of motion here!', '2009-03-28 19:29:05.000000', NULL, 1),
(5405684, 776257, 101256, '<td valign="top">I like this and I know how the image was done because I''ve done similar myself. The problem comes from the lack of overall context.  I know the illusion of the canine type faces is there, but it''s not definitve enough to have any clear sense of "abstract".</td>', 'I like this and I know how the image was done because I''ve done similar myself. The problem comes from the lack of overall context.  I know the illusion of the canine type faces is there, but it''s not definitve enough to have any clear sense of "abstract".', '2009-03-28 19:29:06.000000', NULL, 1),
(5405685, 776334, 86895, '<td valign="top">Nice job showing motion, the colours are nice too.</td>', 'Nice job showing motion, the colours are nice too.', '2009-03-28 19:29:42.000000', NULL, 1),
(5405686, 776389, 101256, '<td valign="top">There is minimalist and then there is MINIMALIST.  This is at the very baseline of being minimalist. It''s good, it''s interesting, but lacking in construction and could do with another loop or something else interesting.</td>', 'There is minimalist and then there is MINIMALIST.  This is at the very baseline of being minimalist. It''s good, it''s interesting, but lacking in construction and could do with another loop or something else interesting.', '2009-03-28 19:30:38.000000', NULL, 1),
(5405687, 775839, 86895, '<td valign="top">Great job showing motion, it reminds me of the old reel to reel movies when all the lines go across the screen.</td>', 'Great job showing motion, it reminds me of the old reel to reel movies when all the lines go across the screen.', '2009-03-28 19:30:46.000000', NULL, 1),
(5405688, 775919, 86895, '<td valign="top">Nice job showing motion.</td>', 'Nice job showing motion.', '2009-03-28 19:31:08.000000', NULL, 1),
(5405689, 776239, 101256, '<td valign="top">This is an action shot that should be much slower - it''s not abstract though.</td>', 'This is an action shot that should be much slower - it''s not abstract though.', '2009-03-28 19:31:14.000000', NULL, 1),
(5405690, 775676, 101256, '<td valign="top">Eh - I get it, flowing water, tweak colors, but - well, hey - it''s not abstract.  It''s just flowing water.</td>', 'Eh - I get it, flowing water, tweak colors, but - well, hey - it''s not abstract.  It''s just flowing water.', '2009-03-28 19:32:04.000000', NULL, 1),
(5405691, 775427, 86895, '<td valign="top">This really looks like an abstract watercolour!  Nicely done :)</td>', 'This really looks like an abstract watercolour!  Nicely done :)', '2009-03-28 19:32:10.000000', NULL, 1),
(5405693, 774707, 86895, '<td valign="top">LOL, I was also thinking that you were playing spin the bottle. :)</td>', 'LOL, I was also thinking that you were playing spin the bottle. :)', '2009-03-28 19:32:43.000000', NULL, 1),
(5405694, 776274, 101256, '<td valign="top">Way over done with movement, but the colors are effective even if the movement isn''t.</td>', 'Way over done with movement, but the colors are effective even if the movement isn''t.', '2009-03-28 19:32:52.000000', NULL, 1),
(5405695, 775834, 86895, '<td valign="top">Nice job capturing motion.</td>', 'Nice job capturing motion.', '2009-03-28 19:33:05.000000', NULL, 1),
(5405697, 776076, 86895, '<td valign="top">Man, this one''s playing tricks with my eyes!  Fantastic job with the motion!!</td>', 'Man, this one''s playing tricks with my eyes!  Fantastic job with the motion!!', '2009-03-28 19:33:36.000000', NULL, 1),
(5405700, 776071, 86895, '<td valign="top">The colours are very vibrant, definitely an attention grabber.</td>', 'The colours are very vibrant, definitely an attention grabber.', '2009-03-28 19:44:50.000000', NULL, 1),
(5405701, 775243, 86895, '<td valign="top">Great job capturing motion.</td>', 'Great job capturing motion.', '2009-03-28 19:45:04.000000', NULL, 1),
(5405702, 776072, 86895, '<td valign="top">Great job capturing motion, not sure it''s abstract.</td>', 'Great job capturing motion, not sure it''s abstract.', '2009-03-28 19:45:34.000000', NULL, 1),
(5405705, 776308, 86895, '<td valign="top">Great job showing motion, the primary colours are really nice.</td>', 'Great job showing motion, the primary colours are really nice.', '2009-03-28 19:47:19.000000', NULL, 1),
(5405711, 775976, 86895, '<td valign="top">First thing I thought was the NIN album, The Downward Spiral.  I like the colours.</td>', 'First thing I thought was the NIN album, The Downward Spiral.  I like the colours.', '2009-03-28 19:52:28.000000', NULL, 1),
(5405712, 776306, 86895, '<td valign="top">There is some motion, just not sure this is abstract.</td>', 'There is some motion, just not sure this is abstract.', '2009-03-28 19:52:58.000000', NULL, 1),
(5405713, 776192, 86895, '<td valign="top">Nice representation of the challenge!</td>', 'Nice representation of the challenge!', '2009-03-28 19:53:46.000000', NULL, 1),
(5405714, 776219, 86895, '<td valign="top">Nice job capturing motion.</td>', 'Nice job capturing motion.', '2009-03-28 19:54:00.000000', NULL, 1),
(5405715, 776193, 86895, '<td valign="top">Nice job capturing motion.</td>', 'Nice job capturing motion.', '2009-03-28 19:54:17.000000', NULL, 1),
(5405717, 776254, 86895, '<td valign="top">I imagine this is what it looks like when you drink too many mojitos! :) Beautiful colours and nice job on the motion!</td>', 'I imagine this is what it looks like when you drink too many mojitos! :) Beautiful colours and nice job on the motion!', '2009-03-28 19:55:17.000000', NULL, 1),
(5405722, 775674, 97166, '<td valign="top">Not incredibly abstract in my view, outside of a conceptual manner that will probably be lost on the majority of DPCers.  The movement of the hands has an interesting feel to it, but the overall photo just doesn''t have enough to it to keep me looking for long.</td>', 'Not incredibly abstract in my view, outside of a conceptual manner that will probably be lost on the majority of DPCers.  The movement of the hands has an interesting feel to it, but the overall photo just doesn''t have enough to it to keep me looking for long.', '2009-03-28 19:59:32.000000', NULL, 1),
(5405723, 774595, 86895, '<td valign="top">I like this, but I think maybe a tighter crop on the rings of water and the "pillar" of water coming back up may have made it look more abstract.</td>', 'I like this, but I think maybe a tighter crop on the rings of water and the "pillar" of water coming back up may have made it look more abstract.', '2009-03-28 19:59:44.000000', NULL, 1),
(5405724, 776031, 97166, '<td valign="top">One of the better zoom blurs I''ve seen, and some great color play.  Abstract in an impressionist way.  I get a kick out of the title.</td>', 'One of the better zoom blurs I''ve seen, and some great color play.  Abstract in an impressionist way.  I get a kick out of the title.', '2009-03-28 20:00:17.000000', NULL, 1),
(5405726, 776142, 86895, '<td valign="top">First thing I noticed was the noise, but I think it grew on me and I think it adds something to this. :)</td>', 'First thing I noticed was the noise, but I think it grew on me and I think it adds something to this. :)', '2009-03-28 20:00:39.000000', NULL, 1),
(5405728, 775776, 86895, '<td valign="top">Nice job showing motion.</td>', 'Nice job showing motion.', '2009-03-28 20:00:55.000000', NULL, 1),
(5405731, 775844, 97166, '<td valign="top">There isn''t much here to tie into the Abstract aspect for me.  Motion, yes, but abstract motion? Not in my view.  It is pretty concrete. (and, er, I don''t mean that as a pun.)</td>', 'There isn''t much here to tie into the Abstract aspect for me.  Motion, yes, but abstract motion? Not in my view.  It is pretty concrete. (and, er, I don''t mean that as a pun.)', '2009-03-28 20:01:19.000000', NULL, 1),
(5405732, 776212, 86895, '<td valign="top">Nice representation of the challenge.  This looks like some sort of futuristic flower.</td>', 'Nice representation of the challenge.  This looks like some sort of futuristic flower.', '2009-03-28 20:01:36.000000', NULL, 1),
(5405733, 776235, 97166, '<td valign="top">I''m not sure what you mean by the title, really, but it detracts from the image itself.  As for that, there''s an ok connection to the abstract, but in my view, the motion connection is next to non-existent.</td>', 'I''m not sure what you mean by the title, really, but it detracts from the image itself.  As for that, there''s an ok connection to the abstract, but in my view, the motion connection is next to non-existent.', '2009-03-28 20:02:38.000000', NULL, 1),
(5405734, 776318, 86895, '<td valign="top">Really great job showing motion.</td>', 'Really great job showing motion.', '2009-03-28 20:02:44.000000', NULL, 1),
