(5406150, 775919, 36141, '<td valign="top">Abstract motion ok, but it doesn''t really say WOW to me. Color is a bit flat, maybe you should have played a little with curves. Try it, it might surprise you.</td>', 'Abstract motion ok, but it doesn''t really say WOW to me. Color is a bit flat, maybe you should have played a little with curves. Try it, it might surprise you.', '2009-03-29 04:07:58.000000', NULL, 1),
(5406153, 775075, 36141, '<td valign="top">You could have gotten more out of this. Composition is ok, colors too, there is motion, but it could have been much more abstract.</td>', 'You could have gotten more out of this. Composition is ok, colors too, there is motion, but it could have been much more abstract.', '2009-03-29 04:10:05.000000', NULL, 1),
(5406154, 776163, 36141, '<td valign="top">There''s abstract motion, but the whole picture doesn''t really WOW me.</td>', 'There''s abstract motion, but the whole picture doesn''t really WOW me.', '2009-03-29 04:12:05.000000', NULL, 1),
(5406157, 775839, 36141, '<td valign="top">Very nice abstract motion, but the colors are a bit flat, it could have used a bit of playing with curves.</td>', 'Very nice abstract motion, but the colors are a bit flat, it could have used a bit of playing with curves.', '2009-03-29 04:13:46.000000', NULL, 1),
(5406161, 776140, 36141, '<td valign="top">If you had played a bit with curves and had pushed it to the ''lightening'' corner, you would have gotten a perfect abstract motion. Try it and you''ll be surprised. If you want me to show it, send me an pm with your email. It would have really improved your image.</td>', 'If you had played a bit with curves and had pushed it to the ''lightening'' corner, you would have gotten a perfect abstract motion. Try it and you''ll be surprised. If you want me to show it, send me an pm with your email. It would have really improved your image.', '2009-03-29 04:20:55.000000', NULL, 1),
(5406163, 775403, 36141, '<td valign="top">There''s motion, but very little abstract. Some playing with the curves (making it much darker) would have done the trick.</td>', 'There''s motion, but very little abstract. Some playing with the curves (making it much darker) would have done the trick.', '2009-03-29 04:23:15.000000', NULL, 1),
(5406166, 776076, 36141, '<td valign="top">Nice abstract motion. Composition is ok.</td>', 'Nice abstract motion. Composition is ok.', '2009-03-29 04:31:17.000000', NULL, 1),
(5406167, 776327, 36141, '<td valign="top">Maybe a bit too much, but overall it''s meeting the rules.</td>', 'Maybe a bit too much, but overall it''s meeting the rules.', '2009-03-29 04:31:43.000000', NULL, 1),
(5406168, 775676, 36141, '<td valign="top">nice abstract motion.</td>', 'nice abstract motion.', '2009-03-29 04:32:26.000000', NULL, 1);
