(5406830, 775909, 100831, '<td valign="top">How is this abstract? I like the background effect of the flowers and grass - it looks like a very pretty oil painting to me. But the bird is the subject of the picture and he''s clear as a bell.</td>', 'How is this abstract? I like the background effect of the flowers and grass - it looks like a very pretty oil painting to me. But the bird is the subject of the picture and he''s clear as a bell.', '2009-03-29 18:16:51.000000', NULL, 1),
(5406832, 775676, 100831, '<td valign="top">The Great Unknown!! (I''ll be looking for the explanation later!) Very nice!</td>', 'The Great Unknown!! (I''ll be looking for the explanation later!) Very nice!', '2009-03-29 18:18:17.000000', NULL, 1),
(5406834, 775657, 100831, '<td valign="top">nice motion, good exposure, but where is the abstract?</td>', 'nice motion, good exposure, but where is the abstract?', '2009-03-29 18:19:06.000000', NULL, 1),
(5406836, 775730, 100831, '<td valign="top">whee!!! Nice one.</td>', 'whee!!! Nice one.', '2009-03-29 18:19:22.000000', NULL, 1),
(5406837, 776101, 100831, '<td valign="top">Lots of motion and a very nice picture, but nothing about it hits me as abstract.</td>', 'Lots of motion and a very nice picture, but nothing about it hits me as abstract.', '2009-03-29 18:20:00.000000', NULL, 1),
(5406839, 775828, 100831, '<td valign="top">Okay. Now that you mention it.... good job.</td>', 'Okay. Now that you mention it.... good job.', '2009-03-29 18:20:47.000000', NULL, 1),
(5406840, 776192, 100831, '<td valign="top">Nice idea but it might be slightly overexposed - unless you were going for that look. I like the blocks of color.</td>', 'Nice idea but it might be slightly overexposed - unless you were going for that look. I like the blocks of color.', '2009-03-29 18:21:40.000000', NULL, 1),
(5406844, 775707, 100831, '<td valign="top">Streets of Fire - a Rock and Roll Fable</td>', 'Streets of Fire - a Rock and Roll Fable', '2009-03-29 18:24:51.000000', NULL, 1),
