INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5406940, 776360, 57447, '<td valign="top">This was easy an easy choice for me.  My best in show - 9.</td>', 'This was easy an easy choice for me.  My best in show - 9.', '2009-03-29 20:02:58.000000', NULL, 1),
(5407012, 776383, 66648, '<td valign="top">This is beautiful. I love how you intertwined the colors. 10/10!</td>', 'This is beautiful. I love how you intertwined the colors. 10/10!', '2009-03-29 20:33:41.000000', NULL, 1),
(5407066, 775254, 47294, '<td valign="top">Nice motion, great colours!</td>', 'Nice motion, great colours!', '2009-03-29 21:24:16.000000', NULL, 1),
(5407070, 774734, 97166, '<td valign="top">Looks like a giant frozen jaw of some ancient, forgotten monster to me.  However, the motion, while I know it''s there, isn''t quite evident as a whole enough to really become the center of the photograph, and thus the theme.</td>', 'Looks like a giant frozen jaw of some ancient, forgotten monster to me.  However, the motion, while I know it''s there, isn''t quite evident as a whole enough to really become the center of the photograph, and thus the theme.', '2009-03-29 21:30:16.000000', NULL, 1),
(5407071, 776101, 97166, '<td valign="top">Lots of motion, not a lot of abstract in my view.</td>', 'Lots of motion, not a lot of abstract in my view.', '2009-03-29 21:30:30.000000', NULL, 1),
(5407073, 776076, 97166, '<td valign="top">I''m getting a little dizzy while contemplating this.  I like that.</td>', 'I''m getting a little dizzy while contemplating this.  I like that.', '2009-03-29 21:30:49.000000', NULL, 1),
(5407074, 776074, 97166, '<td valign="top">Some very nice chaotic energy in this, and the range of red/pink tones is lovely.</td>', 'Some very nice chaotic energy in this, and the range of red/pink tones is lovely.', '2009-03-29 21:31:12.000000', NULL, 1),
(5407075, 776363, 97166, '<td valign="top">Interesting, chaotic energy and pleasing color.</td>', 'Interesting, chaotic energy and pleasing color.', '2009-03-29 21:31:35.000000', NULL, 1),
(5407076, 776163, 97166, '<td valign="top">Very nice use of geometric patterning here, but unfortunately, it doesn''t say ''motion'' to me.</td>', 'Very nice use of geometric patterning here, but unfortunately, it doesn''t say ''motion'' to me.', '2009-03-29 21:32:10.000000', NULL, 1),
(5407077, 776331, 97166, '<td valign="top">A good capture, although it might have worked better for voters to have left out as much of the straw/stick as possible, in order to better disguise the subject.</td>', 'A good capture, although it might have worked better for voters to have left out as much of the straw/stick as possible, in order to better disguise the subject.', '2009-03-29 21:33:02.000000', NULL, 1),
(5407078, 776001, 97166, '<td valign="top">eerie and organic, but the sense of motion isn''t very evident to me.</td>', 'eerie and organic, but the sense of motion isn''t very evident to me.', '2009-03-29 21:33:25.000000', NULL, 1),
(5407079, 776358, 97166, '<td valign="top">Abstract in a conceptual manner, but I don''t think that DPCers were really looking for that kind of abstract.  I imagine that you''re probably getting hit for that.</td>', 'Abstract in a conceptual manner, but I don''t think that DPCers were really looking for that kind of abstract.  I imagine that you''re probably getting hit for that.', '2009-03-29 21:34:06.000000', NULL, 1),
(5407084, 774878, 97166, '<td valign="top">Not a lot of motion evident in this photograph to me.  It looks more like a simple static double exposure.</td>', 'Not a lot of motion evident in this photograph to me.  It looks more like a simple static double exposure.', '2009-03-29 21:38:37.000000', NULL, 1),
(5407086, 776159, 97166, '<td valign="top">Not a very strong abstract feeling to this scene in my eyes.  It''s a little too common a scene.</td>', 'Not a very strong abstract feeling to this scene in my eyes.  It''s a little too common a scene.', '2009-03-29 21:39:28.000000', NULL, 1),
(5407094, 776344, 36141, '<td valign="top">Nice abstract motion. Could have been a bit more expressive I think if you had used a bit more curves (darkening). Overall a good image though.</td>', 'Nice abstract motion. Could have been a bit more expressive I think if you had used a bit more curves (darkening). Overall a good image though.', '2009-03-29 21:42:26.000000', NULL, 1),
(5407099, 776254, 36141, '<td valign="top">It''s meeting the rules. Despite the fact that I''m not too fond of centered images, it''s a nice take on the contest.</td>', 'It''s meeting the rules. Despite the fact that I''m not too fond of centered images, it''s a nice take on the contest.', '2009-03-29 21:45:27.000000', NULL, 1),
(5407102, 776348, 36141, '<td valign="top">A sparkling abstract motion.</td>', 'A sparkling abstract motion.', '2009-03-29 21:45:56.000000', NULL, 1),
(5407107, 775976, 36141, '<td valign="top">It''s meeting the rules and the composition is ok too, not sure about the all blue, but that can be me. I won''t count it in my vote. It''s a good image.</td>', 'It''s meeting the rules and the composition is ok too, not sure about the all blue, but that can be me. I won''t count it in my vote. It''s a good image.', '2009-03-29 21:48:59.000000', NULL, 1),
(5407110, 776389, 36141, '<td valign="top">Not sure about this one. It''s meeting the rules alright, it''s subtle and yet I can''t say WOW, but that can be just me. Won''t vote it low though.</td>', 'Not sure about this one. It''s meeting the rules alright, it''s subtle and yet I can''t say WOW, but that can be just me. Won''t vote it low though.', '2009-03-29 21:51:34.000000', NULL, 1),
(5407112, 776347, 36141, '<td valign="top">Oh pity it still is so recognizable, which makes it hard to say ''abstract''. Wish the little boy would have been all blurred a lot more.</td>', 'Oh pity it still is so recognizable, which makes it hard to say ''abstract''. Wish the little boy would have been all blurred a lot more.', '2009-03-29 21:53:56.000000', NULL, 1),
(5407113, 776342, 36141, '<td valign="top">Nice abstract motion, but I think I would have loved more depth in the blue, it''s a bit flat in color, but that''s only my opinion.</td>', 'Nice abstract motion, but I think I would have loved more depth in the blue, it''s a bit flat in color, but that''s only my opinion.', '2009-03-29 21:56:48.000000', NULL, 1),
(5407114, 776023, 36141, '<td valign="top">Nice take on the contest. Lovely bright colors.</td>', 'Nice take on the contest. Lovely bright colors.', '2009-03-29 21:57:57.000000', NULL, 1),
(5407118, 776261, 36141, '<td valign="top">I''ve seen more roads in this contest and yours is the best sofar. It''s just abstract enough, but could have been more for my taste. Overall a good image.</td>', 'I''ve seen more roads in this contest and yours is the best sofar. It''s just abstract enough, but could have been more for my taste. Overall a good image.', '2009-03-29 22:00:01.000000', NULL, 1),
(5407119, 776162, 36141, '<td valign="top">There''s abstract and there''s motion and the composition is ok too, so I don''t know why I won''t say WOW, but I didn''t vote it low.</td>', 'There''s abstract and there''s motion and the composition is ok too, so I don''t know why I won''t say WOW, but I didn''t vote it low.', '2009-03-29 22:01:52.000000', NULL, 1),
(5407120, 776218, 36141, '<td valign="top">Seems you had more motion in your head than abstract, although it''s better than I have seen on a lot of others. Wish it had been much more abstract. Nevertheless I voted it above average.</td>', 'Seems you had more motion in your head than abstract, although it''s better than I have seen on a lot of others. Wish it had been much more abstract. Nevertheless I voted it above average.', '2009-03-29 22:04:33.000000', NULL, 1),
(5407121, 774501, 36141, '<td valign="top">For me it''s still too much fish and too little abstract, though there are some very nice abstract parts in it.</td>', 'For me it''s still too much fish and too little abstract, though there are some very nice abstract parts in it.', '2009-03-29 22:06:07.000000', NULL, 1),
(5407133, 775899, 36141, '<td valign="top">Stopped motion rather than abstract motion.<br/> <br/>Definition of Abstract is: art in which the subject is represented by shapes and patterns rather than by a realistic likeness.</td>', 'Stopped motion rather than abstract motion. Definition of Abstract is: art in which the subject is represented by shapes and patterns rather than by a realistic likeness.', '2009-03-29 22:12:36.000000', NULL, 1),
(5407135, 775555, 36141, '<td valign="top">Very nice abstract motion.</td>', 'Very nice abstract motion.', '2009-03-29 22:12:58.000000', NULL, 1),
(5407137, 776159, 36141, '<td valign="top">Oh I wish the branches wouldn''t have looked so realistic like branches, they take down the beautiful upperhalf blue abstract motion.</td>', 'Oh I wish the branches wouldn''t have looked so realistic like branches, they take down the beautiful upperhalf blue abstract motion.', '2009-03-29 22:14:47.000000', NULL, 1),
(5407140, 776370, 36141, '<td valign="top">Ah love this. I love when I can think up a story from an abstract image.<br/>Great take on the contest.</td>', 'Ah love this. I love when I can think up a story from an abstract image.Great take on the contest.', '2009-03-29 22:16:05.000000', NULL, 1),
(5407141, 775580, 36141, '<td valign="top">First one I come across that is what it should be, Abstract Motion.<br/>Very nice, love it.</td>', 'First one I come across that is what it should be, Abstract Motion.Very nice, love it.', '2009-03-29 22:16:33.000000', NULL, 1),
(5407162, 776159, 103142, '<td valign="top">Very interesting photo. I like it quite a bit.</td>', 'Very interesting photo. I like it quite a bit.', '2009-03-29 22:31:37.000000', NULL, 1),
(5407163, 775061, 103142, '<td valign="top">Intriguing photo. I like the colors. I''m curious what it would look like a tad brighter.</td>', 'Intriguing photo. I like the colors. I''m curious what it would look like a tad brighter.', '2009-03-29 22:32:09.000000', NULL, 1),
(5407166, 774994, 103142, '<td valign="top">Interesting. Nice colors. I''m not sure the bottom half adds that much to the photo...</td>', 'Interesting. Nice colors. I''m not sure the bottom half adds that much to the photo...', '2009-03-29 22:32:38.000000', NULL, 1),
(5407167, 775730, 103142, '<td valign="top">Very nice photo--wonderful colors.</td>', 'Very nice photo--wonderful colors.', '2009-03-29 22:32:50.000000', NULL, 1),
(5407168, 776348, 103142, '<td valign="top">Awesome photo! I hope you explain how you got it.</td>', 'Awesome photo! I hope you explain how you got it.', '2009-03-29 22:33:09.000000', NULL, 1),
(5407169, 776268, 103142, '<td valign="top">Very well done. Enjoyable.</td>', 'Very well done. Enjoyable.', '2009-03-29 22:33:22.000000', NULL, 1),
(5407171, 776390, 103142, '<td valign="top">Very nicely done! I like the colors.</td>', 'Very nicely done! I like the colors.', '2009-03-29 22:33:38.000000', NULL, 1),
(5407172, 775536, 103142, '<td valign="top">I like the soft colors. nicely done.</td>', 'I like the soft colors. nicely done.', '2009-03-29 22:33:51.000000', NULL, 1),
(5407174, 775827, 103142, '<td valign="top">Very nice shot. But I''ve been using the definition: "Of, relating to, or being a style of art in which natural objects are not represented realistically." With this in mind, it really doesn''t fit abstract, IMO.</td>', 'Very nice shot. But I''ve been using the definition: "Of, relating to, or being a style of art in which natural objects are not represented realistically." With this in mind, it really doesn''t fit abstract, IMO.', '2009-03-29 22:34:46.000000', NULL, 1),
(5407176, 775026, 103142, '<td valign="top">Very interesting photo. Well done.</td>', 'Very interesting photo. Well done.', '2009-03-29 22:34:57.000000', NULL, 1),
(5407177, 776089, 103142, '<td valign="top">Very nice colors, good photo. Would be interested to see what it looked like just a tad brighter.</td>', 'Very nice colors, good photo. Would be interested to see what it looked like just a tad brighter.', '2009-03-29 22:35:22.000000', NULL, 1),
(5407280, 774449, 100831, '<td valign="top">nice! It''s definitely abstract and with a painterly motion.</td>', 'nice! It''s definitely abstract and with a painterly motion.', '2009-03-30 00:29:23.000000', NULL, 1),
(5407282, 776031, 100831, '<td valign="top">what''s the opposite of centrifugal motion? Nice idea carried out very well!</td>', 'what''s the opposite of centrifugal motion? Nice idea carried out very well!', '2009-03-30 00:30:11.000000', NULL, 1),
(5407283, 775514, 100831, '<td valign="top">interesting shape and colors</td>', 'interesting shape and colors', '2009-03-30 00:30:38.000000', NULL, 1),
(5407285, 776212, 100831, '<td valign="top">very cool - lots of motion - love it!!</td>', 'very cool - lots of motion - love it!!', '2009-03-30 00:31:02.000000', NULL, 1),
(5407286, 774849, 100831, '<td valign="top">you shouldn''t do that, you know (except in this case) - excellent!!</td>', 'you shouldn''t do that, you know (except in this case) - excellent!!', '2009-03-30 00:31:29.000000', NULL, 1),
(5407288, 776383, 100831, '<td valign="top">nice compostion and color - and a wonderful abstract</td>', 'nice compostion and color - and a wonderful abstract', '2009-03-30 00:32:00.000000', NULL, 1),
(5407289, 776139, 100831, '<td valign="top">I almost hear the motion. But I don''t see the abstract.</td>', 'I almost hear the motion. But I don''t see the abstract.', '2009-03-30 00:32:29.000000', NULL, 1),
(5407292, 776268, 100831, '<td valign="top">I like this lens effect - excellent - not too abstract, but it''s enough, imo.</td>', 'I like this lens effect - excellent - not too abstract, but it''s enough, imo.', '2009-03-30 00:34:09.000000', NULL, 1),
(5407293, 775910, 100831, '<td valign="top">nice thick drips of whatever they are. Great color!</td>', 'nice thick drips of whatever they are. Great color!', '2009-03-30 00:35:10.000000', NULL, 1),
(5407296, 775785, 100831, '<td valign="top">nice motion. nice black and white contrast. But it''s not really an abstract.</td>', 'nice motion. nice black and white contrast. But it''s not really an abstract.', '2009-03-30 00:35:54.000000', NULL, 1),
(5407299, 776358, 100831, '<td valign="top">abstract for color. motion gets a 6.</td>', 'abstract for color. motion gets a 6.', '2009-03-30 00:36:49.000000', NULL, 1),
(5407300, 776331, 100831, '<td valign="top">I think this is really nice - I might have preferred not being told what it is but I love the motion, the colors, and the idea.</td>', 'I think this is really nice - I might have preferred not being told what it is but I love the motion, the colors, and the idea.', '2009-03-30 00:38:05.000000', NULL, 1),
(5407303, 774874, 100831, '<td valign="top">Screamingly terrific! Great great color and motion - I almost hear the whirlwind.</td>', 'Screamingly terrific! Great great color and motion - I almost hear the whirlwind.', '2009-03-30 00:39:13.000000', NULL, 1),
(5407305, 775202, 100831, '<td valign="top">Nice abstract!! Great color and presentation.</td>', 'Nice abstract!! Great color and presentation.', '2009-03-30 00:39:50.000000', NULL, 1),
(5407805, 776230, 30364, '<td valign="top"><i>If only I had wings <br/>Wings as white as yours <br/>Up into the sky <br/>I''d surely fly </i> <br/> <br/>Well thank you.  I knew nothing of Hyde and the Roentgen Stories until I saw this and went where it took me.  Beautiful photograph too.  9.</td>', 'If only I had wings Wings as white as yours Up into the sky I''d surely fly   Well thank you.  I knew nothing of Hyde and the Roentgen Stories until I saw this and went where it took me.  Beautiful photograph too.  9.', '2009-03-30 08:07:24.000000', NULL, 1),
(5407808, 775282, 30364, '<td valign="top">Yes, that looks about right.  I see a giant hieroglyph, scratched into the planetary surface.  Beautiful amalgam of tone, texture and color in this image.  There''s just enough of everything; not too much of anything.  It''s lovely.  9.</td>', 'Yes, that looks about right.  I see a giant hieroglyph, scratched into the planetary surface.  Beautiful amalgam of tone, texture and color in this image.  There''s just enough of everything; not too much of anything.  It''s lovely.  9.', '2009-03-30 08:11:57.000000', NULL, 1),
(5407810, 775580, 30364, '<td valign="top">I see what it is, but it actually suggested a glimpse of an ancient hominoid to me, celebrating some small triumph over environment (and see where that''s got us now!)</td>', 'I see what it is, but it actually suggested a glimpse of an ancient hominoid to me, celebrating some small triumph over environment (and see where that''s got us now!)', '2009-03-30 08:17:19.000000', NULL, 1),
(5407812, 775536, 30364, '<td valign="top">Quite beautiful.  It''s a seascape and a landscape, but there''s no point at which one becomes the other.  9.</td>', 'Quite beautiful.  It''s a seascape and a landscape, but there''s no point at which one becomes the other.  9.', '2009-03-30 08:18:25.000000', NULL, 1),
(5407822, 776340, 30364, '<td valign="top">Very lovely.  It reminds me of a famous painting that''s so famous I can''t recall it.  But it''s good.  Just like this.  9.</td>', 'Very lovely.  It reminds me of a famous painting that''s so famous I can''t recall it.  But it''s good.  Just like this.  9.', '2009-03-30 08:28:07.000000', NULL, 1),
(5407825, 775676, 30364, '<td valign="top">It''s interesting you should say that because even the primordial chaos is governed by the universal laws.  So there is an order here, beneath all the disorder.  It''s a very comforting thought.  Religion for the non-credulous.  9.</td>', 'It''s interesting you should say that because even the primordial chaos is governed by the universal laws.  So there is an order here, beneath all the disorder.  It''s a very comforting thought.  Religion for the non-credulous.  9.', '2009-03-30 08:33:11.000000', NULL, 1),
(5407839, 775026, 30364, '<td valign="top">Yes.  It''s very beautiful.  Not exactly abstract in literal terms, but certainly it is so in a figurative sense.  There''s a suggestion of yin-yang, and another of the out-of-body excursion referred to in the title.  Acid trip for those of us who remember the 60s (which nobody does).  I don''t know what it means, but I like how it looks and how it makes me feel when I look at it for a while.  9.</td>', 'Yes.  It''s very beautiful.  Not exactly abstract in literal terms, but certainly it is so in a figurative sense.  There''s a suggestion of yin-yang, and another of the out-of-body excursion referred to in the title.  Acid trip for those of us who remember the 60s (which nobody does).  I don''t know what it means, but I like how it looks and how it makes me feel when I look at it for a while.  9.', '2009-03-30 08:56:44.000000', NULL, 1),
(5407855, 776050, 30364, '<td valign="top">What a fabulous photograph.  It''s not at all abstract of course, but who cares about that?  It''s truly brilliant in every way.  It encapsulates all that is thrilling and magical about photography.  Among other things, it affirms the wonderful fact that photograph really is capable of being the art for everybody.  If I could take just one picture like this in all of my life, I''d be happy with my photography.  I''d probably even be smug.  Well, I admit I''m already smug, but this would give me something to be smug about.  10.  And the Order of the Thumb:<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=748778" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/30000-34999/30364/120/748778.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/30000-34999/30364/120/748778.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/30000-34999/30364/120/748778.jpg"/></a></td>', 'What a fabulous photograph.  It''s not at all abstract of course, but who cares about that?  It''s truly brilliant in every way.  It encapsulates all that is thrilling and magical about photography.  Among other things, it affirms the wonderful fact that photograph really is capable of being the art for everybody.  If I could take just one picture like this in all of my life, I''d be happy with my photography.  I''d probably even be smug.  Well, I admit I''m already smug, but this would give me something to be smug about.  10.  And the Order of the Thumb:', '2009-03-30 09:14:15.000000', NULL, 1),
(5407857, 775976, 96534, '<td valign="top">Gee, this is pretty amazing</td>', 'Gee, this is pretty amazing', '2009-03-30 09:14:31.000000', NULL, 1),
