(5408049, 775778, 96534, '<td valign="top">this is very mind warping, I like it</td>', 'this is very mind warping, I like it', '2009-03-30 10:13:14.000000', NULL, 1),
(5408057, 775043, 105047, '<td valign="top">I love how the eye is drawn in a sweeping motion across the shot. What better picture to show motion than one that makes you move. I would like to stand in front of this pic blown up to about 6ft across for a while. Great job. 9</td>', 'I love how the eye is drawn in a sweeping motion across the shot. What better picture to show motion than one that makes you move. I would like to stand in front of this pic blown up to about 6ft across for a while. Great job. 9', '2009-03-30 10:21:07.000000', NULL, 1),
(5408069, 775730, 105047, '<td valign="top">Good choice in not centering the focal point. I also really like the different colors (im partially color-blind, so contrasting colors kind of fascinate me).</td>', 'Good choice in not centering the focal point. I also really like the different colors (im partially color-blind, so contrasting colors kind of fascinate me).', '2009-03-30 10:34:20.000000', NULL, 1),
(5408075, 776067, 105047, '<td valign="top">Wow. What a great idea. What an excellent effect. They look like flowers, or dancers with large caricatured heads. I must now find cool road-bumps around my house :) Sounds like a good challenge, actually.</td>', 'Wow. What a great idea. What an excellent effect. They look like flowers, or dancers with large caricatured heads. I must now find cool road-bumps around my house :) Sounds like a good challenge, actually.', '2009-03-30 10:40:56.000000', NULL, 1),
(5408078, 775844, 105047, '<td valign="top">That dude is so cool. I like how his feet (and even his profile) are suggesting movement.</td>', 'That dude is so cool. I like how his feet (and even his profile) are suggesting movement.', '2009-03-30 10:45:00.000000', NULL, 1),
(5408086, 776218, 105047, '<td valign="top">Wow, that title makes this shot really creepy. The motion captures the sense of a mad dash very nicely.</td>', 'Wow, that title makes this shot really creepy. The motion captures the sense of a mad dash very nicely.', '2009-03-30 10:48:44.000000', NULL, 1),
(5408092, 775812, 105047, '<td valign="top">Smoke shots are the greatest. Ha! I see Don Quixote in profile facing right. The different colors in the smoke are really impressive. In fact, I think it''s the different colors that are creating the face for me. Excellent shot.</td>', 'Smoke shots are the greatest. Ha! I see Don Quixote in profile facing right. The different colors in the smoke are really impressive. In fact, I think it''s the different colors that are creating the face for me. Excellent shot.', '2009-03-30 10:53:18.000000', NULL, 1),
