(5409293, 776333, 103142, '<td valign="top">I''ve been using the definition: "Of, relating to, or being a style of art in which natural objects are not represented realistically." With this in mind, it just seems blurry.</td>', 'I''ve been using the definition: "Of, relating to, or being a style of art in which natural objects are not represented realistically." With this in mind, it just seems blurry.', '2009-03-30 23:27:16.000000', NULL, 1),
(5409295, 776330, 103584, '<td valign="top">Hi,  Where''s the LHC in this one?  Yes, there''s colors for the gluons but that''s certainly not the Higgs is all about.</td>', 'Hi,  Where''s the LHC in this one?  Yes, there''s colors for the gluons but that''s certainly not the Higgs is all about.', '2009-03-30 23:27:36.000000', NULL, 1),
